# Search for each TODO song and collect release dates directly from search results.
spotify_token = spotify_login['access_token']
song_releases = {}
for song in todo_songs:
    search_result = apis.spotify.search_songs(access_token=spotify_token, query=song['title'])
    matches = []
    for s in search_result:
        if s['title'].lower() == song['title'].lower():
            song_artists = set(a['name'].lower() for a in s.get('artists', []))
            target_artists = set(a.strip().lower() for a in song['artists'].split(','))
            if song_artists & target_artists:
                matches.append(s)
    print(song['title'], 'matches:', len(matches))
    if matches:
        release_date = matches[0]['release_date']
        # Extract month/year in format MM/YYYY
        from datetime import datetime
        dt = datetime.fromisoformat(release_date)
        song_releases[song['title']] = f"{dt.month:02d}/{dt.year}"
        print(song['title'], '->', song_releases[song['title']])

